import torch

def relu(x):
    # 严格 > 0：明确零点处的反向传播约定。
    return torch.where(x > 0, x, torch.zeros_like(x))

import torch

def relu_backward(x, grad_output):
    return grad_output * (x > 0).to(x.dtype)

import torch

def sigmoid(x):
    pos = 1 / (1 + torch.exp(-x.clamp_min(0)))
    e = torch.exp(x.clamp_max(0))
    neg = e / (1 + e)
    return torch.where(x >= 0, pos, neg)

