def inbatch_softmax_loss(users, items, temperature=0.1):
    scores = (users @ items.T) / temperature
    scores = scores - scores.amax(dim=1, keepdim=True)
    return (torch.logsumexp(scores, dim=1) - scores.diagonal()).mean()

