def mmoe(x, weights):
    w = weights
    experts = torch.relu(torch.einsum('bd,ehd->beh', x, w['expert_w']) + w['expert_b'])
    gates = torch.softmax(torch.einsum('bd,ted->bte', x, w['gate_w']) + w['gate_b'], dim=-1)
    return torch.einsum('bte,beh->bth', gates, experts)

