def temperature_softmax(logits, temperature=1.0, dim=-1):
    shifted = (logits - logits.amax(dim=dim, keepdim=True)) / temperature
    numerator = shifted.exp()
    return numerator / numerator.sum(dim=dim, keepdim=True)

