def categorical_entropy(logits):
    shifted = logits - logits.amax(-1, keepdim=True)
    log_probs = shifted - torch.logsumexp(shifted, dim=-1, keepdim=True)
    return -(log_probs.exp() * log_probs).sum(-1)

